#include "Editor.h"
void BundleLook::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float p,float start,float end,juce::Slider& s){const float r=juce::jmin(w,h)*.35f,cx=x+w*.5f,cy=y+h*.5f,a=start+p*(end-start);auto colour=s.findColour(juce::Slider::rotarySliderFillColourId);juce::Path track,value;track.addCentredArc(cx,cy,r,r,0,start,end,true);value.addCentredArc(cx,cy,r,r,0,start,a,true);g.setColour(juce::Colour(0xff22323f));g.strokePath(track,juce::PathStrokeType(2));for(int i=3;i>=1;--i){g.setColour(colour.withAlpha(.05f*float(4-i)));g.strokePath(value,juce::PathStrokeType(float(2+2*i)));}g.setColour(colour);g.strokePath(value,juce::PathStrokeType(2.5f));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff3b5260),cx-r,cy-r,juce::Colour(0xff080d14),cx+r,cy+r,false));g.fillEllipse(cx-r+4,cy-r+4,2*r-8,2*r-8);g.setColour(juce::Colour(0xff4b6778));g.drawEllipse(cx-r+4,cy-r+4,2*r-8,2*r-8,1);g.setColour(colour);g.drawLine(cx+std::sin(a)*r*.25f,cy-std::cos(a)*r*.25f,cx+std::sin(a)*r*.7f,cy-std::cos(a)*r*.7f,2.4f);}
void MatrixPad::paint(juce::Graphics& g){auto b=getLocalBounds().toFloat().reduced(3);auto c=juce::Colour(processor.product().colour);g.setColour(juce::Colour(0xff11172a));g.fillRoundedRectangle(b,10);g.setColour(c.withAlpha(.25f));g.drawRoundedRectangle(b,10,1);for(int i=1;i<4;++i){float t=float(i)/4;g.drawLine(b.getX()+b.getWidth()*t,b.getY(),b.getX()+b.getWidth()*t,b.getBottom());g.drawLine(b.getX(),b.getY()+b.getHeight()*t,b.getRight(),b.getY()+b.getHeight()*t);}float x=processor.apvts.getRawParameterValue("motion")->load()*.01f,y=processor.apvts.getRawParameterValue("synth")->load()*.01f;float px=b.getX()+x*b.getWidth(),py=b.getBottom()-y*b.getHeight();for(int r=14;r>=4;r-=5){g.setColour(c.withAlpha(.14f));g.fillEllipse(px-r,py-r,float(r*2),float(r*2));}g.setColour(c);g.fillEllipse(px-3,py-3,6,6);g.setFont(juce::Font(10.f));g.drawText("AURA / PESO + SINTESE",b.reduced(5).toNearestInt(),juce::Justification::centredBottom);}
void MatrixPad::set(const juce::MouseEvent& e){auto b=getLocalBounds().toFloat().reduced(3);float x=juce::jlimit(0.f,1.f,(e.position.x-b.getX())/b.getWidth()),y=juce::jlimit(0.f,1.f,(b.getBottom()-e.position.y)/b.getHeight());for(const auto& pair:std::array<std::pair<const char*,float>,3>{{{"motion",x*100},{"synth",y*100},{"sub",y*8}}})if(auto* p=processor.apvts.getParameter(pair.first))p->setValueNotifyingHost(p->convertTo0to1(pair.second));repaint();}
void MatrixPad::mouseDown(const juce::MouseEvent& e){gesture=true;for(auto id:{"motion","synth","sub"})processor.apvts.getParameter(id)->beginChangeGesture();set(e);}
void MatrixPad::mouseDrag(const juce::MouseEvent& e){set(e);}
void MatrixPad::mouseUp(const juce::MouseEvent&){if(gesture){for(auto id:{"motion","synth","sub"})processor.apvts.getParameter(id)->endChangeGesture();gesture=false;}}
BundleEditor::BundleEditor(BundleProcessor& p):AudioProcessorEditor(&p),processor(p),pad(p){setOpaque(true);setLookAndFeel(&look);auto colour=juce::Colour(p.product().colour);for(size_t i=0;i<8;++i){const auto& c=p.product().controls[i];auto& k=knobs[i];k.setName(c.id);k.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k.setTextBoxStyle(juce::Slider::TextBoxBelow,false,96,16);k.setColour(juce::Slider::rotarySliderFillColourId,colour);k.setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xff344752));k.setTextValueSuffix(juce::String(" ")+c.unit);k.setTooltip(juce::String(c.label)+" / "+c.unit);addAndMakeVisible(k);labels[i].setText(c.label,juce::dontSendNotification);labels[i].setFont(juce::Font(10.f,juce::Font::bold));labels[i].setJustificationType(juce::Justification::centred);labels[i].setColour(juce::Label::textColourId,juce::Colour(0xffb4cbd6));addAndMakeVisible(labels[i]);attachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,c.id,k));}
 for(int j=0;j<2;++j){auto& s=j?output:input;s.setName(j?"output":"input");s.setSliderStyle(juce::Slider::LinearHorizontal);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,55,18);s.setColour(juce::Slider::thumbColourId,colour);s.setTooltip(j?"Saida (dB). Apex limita ganho positivo.":"Entrada (dB)");addAndMakeVisible(s);attachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,j?"output":"input",s));}
 presets.setName("presets");for(int i=0;i<p.getNumPrograms();++i)presets.addItem(p.getProgramName(i),i+1);presets.setSelectedId(p.getCurrentProgram()+1,juce::dontSendNotification);presets.setColour(juce::ComboBox::backgroundColourId,juce::Colour(0xff142331));presets.setColour(juce::ComboBox::textColourId,colour);presets.onChange=[this]{processor.setCurrentProgram(presets.getSelectedId()-1);};addAndMakeVisible(presets);if(p.getKind()==1){timbre.setName("Timbre Metta");timbre.addItem("Original 3.0",1);timbre.addItem("Corpo 87",2);timbre.addItem("Tubo 12",3);timbre.setColour(juce::ComboBox::backgroundColourId,juce::Colour(0xff142b27));timbre.setColour(juce::ComboBox::textColourId,colour);timbre.setTooltip("Perfis tonais Metta: nao sao modelos fisicos de microfone nem presets pessoais de terceiros.");addAndMakeVisible(timbre);timbreAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.apvts,"micProfile",timbre);}if(p.getKind()==1){addAndMakeVisible(focus);addAndMakeVisible(match);focus.setTooltip("Motor novo. Desligado preserva o processamento classico.");match.setTooltip("Compensa volume para comparar com BYPASS. Nao e limiter.");focusAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.apvts,"focus",focus);matchAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.apvts,"match",match);}addAndMakeVisible(bypass);bypassAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.apvts,"bypass",bypass);status.setFont(juce::Font(10.f));status.setColour(juce::Label::textColourId,colour);status.setJustificationType(juce::Justification::centred);addAndMakeVisible(status);addChildComponent(pad);pad.setVisible(p.getKind()==3);setResizable(true,true);setResizeLimits(660,360,990,540);setSize(660,360);startTimerHz(20);timerCallback();}
BundleEditor::~BundleEditor(){stopTimer();setLookAndFeel(nullptr);}
void BundleEditor::resized(){int w=getWidth(),h=getHeight();bypass.setBounds(w-115,13,100,25);if(processor.getKind()==1){focus.setBounds(w-280,13,80,25);match.setBounds(w-200,13,80,25);}presets.setBounds(16,64,w-(processor.getKind()==1?272:88),26);if(processor.getKind()==1)timbre.setBounds(w-248,64,176,26);const int areaW=w-88,areaH=h-159;if(processor.getKind()!=3){int cell=areaW/4,row=areaH/2;for(int i=0;i<8;++i){int x=16+(i%4)*cell,y=104+(i/4)*row;labels[size_t(i)].setBounds(x,y,cell,14);knobs[size_t(i)].setBounds(x,y+15,cell,row-16);}}else{int side=areaW/4,row=areaH/3;const int left[3]{0,2,4},right[3]{5,6,7};for(int i=0;i<8;++i){bool visible=i!=1&&i!=3;knobs[size_t(i)].setVisible(visible);labels[size_t(i)].setVisible(visible);}for(int r=0;r<3;++r)for(int c=0;c<2;++c){int i=c?right[r]:left[r],x=c?16+areaW-side:16,y=104+r*row;labels[size_t(i)].setBounds(x,y,side,14);knobs[size_t(i)].setBounds(x,y+14,side,row-15);}pad.setBounds(20+side,108,areaW-side*2-8,areaH-12);}

 input.setBounds(68,h-47,(w-195)/2,20);output.setBounds(115+(w-195)/2,h-47,(w-195)/2,20);status.setBounds(16,h-23,w-85,18);}
void BundleEditor::timerCallback(){juce::String text;if(processor.apvts.getRawParameterValue("bypass")->load()>.5f)text="BYPASS / AUDIO ORIGINAL";else if(processor.getKind()==6)text="M "+juce::String(processor.lufsM.load(),1)+"  S "+juce::String(processor.lufsS.load(),1)+"  I "+juce::String(processor.lufsI.load(),1)+" LUFS  /  TP "+juce::String(processor.tpDb.load(),1)+" dBTP";else text="GR "+juce::String(processor.grDb.load(),1)+" dB  /  MONO "+juce::String(processor.correlation.load(),2)+"  /  DUCK "+juce::String(mv3::db(processor.duck.load()),1)+" dB";status.setText(text,juce::dontSendNotification);presets.setSelectedId(processor.getCurrentProgram()+1,juce::dontSendNotification);pad.repaint();repaint();}
void BundleEditor::paint(juce::Graphics& g){int w=getWidth(),h=getHeight();auto c=juce::Colour(processor.product().colour);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff182532),0,0,juce::Colour(0xff070b13),float(w),float(h),false));g.fillAll();g.setColour(juce::Colour(0xffe5f5ff));g.setFont(juce::Font(20.f,juce::Font::bold));g.drawText(processor.product().name,16,8,w-140,27,juce::Justification::centredLeft);g.setColour(c);g.setFont(juce::Font(10.f));g.drawText("METTAVOXAD 3.0.3 BUNDLE  /  "+juce::String(processor.product().role),16,37,w-100,18,juce::Justification::centredLeft);g.setColour(c.withAlpha(.25f));g.drawRoundedRectangle(12,97,float(w-80),float(h-151),9,1);g.setColour(juce::Colour(0xffa4bbc8));g.drawText("IN dB",16,h-47,52,20,juce::Justification::centredLeft);g.drawText("OUT dB",70+(w-195)/2,h-47,45,20,juce::Justification::centredLeft);g.drawText("OUT",w-56,70,42,15,juce::Justification::centred);const float levels[]{processor.leftDb.load(),processor.rightDb.load()};for(int ch=0;ch<2;++ch){float x=float(w-49+ch*18),height=float(h-137);g.setColour(juce::Colour(0xff22323e));g.fillRoundedRectangle(x,96,10,height,3);float f=juce::jlimit(0.f,1.f,(levels[ch]+60)/60)*height;g.setGradientFill(juce::ColourGradient(juce::Colour(0xffffb84c),x,96,c,x,96+height,false));if(f>0)g.fillRoundedRectangle(x,96+height-f,10,f,3);g.setColour(juce::Colour(0xffa4bbc8));g.drawText(ch?"R":"L",int(x)-1,h-34,13,15,juce::Justification::centred);}}
